const dishes=[
{id:1,name:'宫保鸡丁',en:'KUNG PAO CHICKEN',description:'鸡肉鲜嫩 · 花生酥香 · 酸甜微辣',price:32,category:'招牌热菜',spicy:true,veg:false,sales:268,rating:'99%',badge:'人气 TOP 1',position:'0% 0%'},
{id:2,name:'外婆红烧肉',en:'BRAISED PORK',description:'慢火细炖 · 肥而不腻 · 入口即化',price:48,category:'招牌热菜',spicy:false,veg:false,sales:216,rating:'98%',badge:'主厨推荐',position:'50% 0%'},
{id:3,name:'麻婆豆腐',en:'MAPO TOFU',description:'嫩滑豆腐 · 麻辣鲜香 · 下饭首选',price:22,category:'招牌热菜',spicy:true,veg:false,sales:192,rating:'98%',badge:'下饭神器',position:'100% 0%'},
{id:4,name:'清炒时蔬',en:'SEASONAL GREENS',description:'当季青菜 · 清脆爽口 · 自然鲜甜',price:18,category:'田园时蔬',spicy:false,veg:true,sales:156,rating:'99%',badge:'清新之选',position:'0% 100%'},
{id:5,name:'现炸小酥肉',en:'CRISPY PORK',description:'外酥里嫩 · 椒香四溢 · 趁热吃',price:28,category:'小食凉菜',spicy:false,veg:false,sales:183,rating:'98%',badge:'现炸现吃',position:'50% 100%'},
{id:6,name:'番茄炒鸡蛋',en:'TOMATO & EGGS',description:'酸甜番茄 · 松软鸡蛋 · 记忆里的味道',price:20,category:'田园时蔬',spicy:false,veg:true,sales:205,rating:'99%',badge:'家的味道',position:'100% 100%'},
{id:7,name:'五常香米饭',en:'STEAMED RICE',description:'精选香米 · 颗粒饱满 · 软糯清香',price:3,category:'米饭主食',spicy:false,veg:true,sales:356,rating:'99%',badge:'一碗满足',position:'0% 0%',emoji:'🍚'},
{id:8,name:'冰镇酸梅汤',en:'PLUM JUICE',description:'乌梅慢煮 · 酸甜解腻 · 清爽一杯',price:8,category:'清爽饮品',spicy:false,veg:true,sales:126,rating:'98%',badge:'解辣搭档',position:'50% 0%',emoji:'🥤'},
{id:9,name:'桂花乌龙茶',en:'OSMANTHUS OOLONG',description:'桂花清香 · 乌龙回甘 · 温热舒心',price:12,category:'清爽饮品',spicy:false,veg:true,sales:98,rating:'99%',badge:'暖心好茶',position:'100% 0%',emoji:'🍵'}];
const categories=[['人气推荐','✦',6],['招牌热菜','♨',3],['田园时蔬','♧',2],['小食凉菜','♢',1],['米饭主食','▱',1],['清爽饮品','♜',2]];
const $=s=>document.querySelector(s);const money=n=>'¥'+n.toFixed(2);let category='人气推荐',filter='all',query='';let cart={};let orders=[];let toastTimer;let modalMode='';
function readLocal(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
const stored=readLocal('shiguang-cart',{});if(stored&&typeof stored==='object'&&!Array.isArray(stored))for(const d of dishes)if(Number.isInteger(stored[d.id])&&stored[d.id]>0)cart[d.id]=Math.min(stored[d.id],99);
const storedOrders=readLocal('shiguang-orders',[]);if(Array.isArray(storedOrders))orders=storedOrders.filter(o=>o&&typeof o.id==='string'&&Array.isArray(o.items)).slice(0,30);
function saveLocal(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2700)}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function totals(){return Object.entries(cart).reduce((s,[id,n])=>{const d=dishes.find(d=>d.id===+id);if(d){s.count+=n;s.amount+=d.price*n}return s},{count:0,amount:0})}
function photo(d,cls=''){return d.emoji?`<div class="food-photo ${cls}" style="background-image:none;background:linear-gradient(135deg,#f3ebd9,#e6e9d9);display:grid;place-items:center;font-size:${cls==='cart-thumb'?'28':'65'}px" role="img" aria-label="${d.name}">${d.emoji}</div>`:`<div class="food-photo ${cls}" style="background-position:${d.position}" role="img" aria-label="${d.name}"></div>`}
function counter(d){const n=cart[d.id]||0;return n?`<div class="counter"><button data-change="-1" data-id="${d.id}" aria-label="减少${d.name}">−</button><span>${n}</span><button data-change="1" data-id="${d.id}" aria-label="增加${d.name}">+</button></div>`:`<button class="add" data-change="1" data-id="${d.id}" aria-label="添加${d.name}">+</button>`}
function renderCategories(){$('#categories').innerHTML=categories.map(([name,icon,n])=>`<button class="category ${category===name?'active':''}" data-category="${name}" aria-pressed="${category===name}"><span class="cat-icon">${icon}</span>${name}<small>${String(n).padStart(2,'0')}</small></button>`).join('')}
function renderMenu(){let list=dishes.filter(d=>(category==='人气推荐'?d.id<=6:d.category===category)&&(!query||`${d.name}${d.description}${d.en}`.toLowerCase().includes(query.toLowerCase()))&&(filter==='all'||filter==='mild'&&!d.spicy||filter==='spicy'&&d.spicy||filter==='veg'&&d.veg));$('#category-title').innerHTML=`${category} <span id="result-count">${list.length} 道用心好菜</span>`;$('#dish-grid').innerHTML=list.map(d=>`<article class="dish-card"><div class="dish-picture">${photo(d,'dish-picture')}<span class="dish-badge ${d.id<=3?'orange':''}">${d.badge}</span></div><div class="dish-info"><div class="dish-name">${d.name}<span class="spice">${d.spicy?'♨ 微辣':d.veg?'♧':''}</span></div><p class="dish-description">${d.description}</p><div class="dish-meta"><span>好评 ${d.rating}</span><span>·</span><span>月售 ${d.sales}+</span></div><div class="dish-price-row"><div class="price"><small>¥</small>${d.price}<span class="unit">/ ${d.id===7?'碗':d.id>=8?'杯':'份'}</span></div>${counter(d)}</div></div></article>`).join('');$('#empty-search').hidden=!!list.length}
function renderCart(){const {count,amount}=totals();$('#cart-count').textContent=count;$('#total-count').textContent=`共 ${count} 份`;$('#subtotal').textContent=money(amount);$('#total').innerHTML=`¥${amount}<small>.00</small>`;$('#mobile-count').textContent=count;$('#mobile-total').textContent=money(amount)+' →';$('#checkout').disabled=!count;$('#clear-cart').disabled=!count;$('#cart-empty').hidden=!!count;$('#cart-items').innerHTML=Object.entries(cart).map(([id,n])=>{const d=dishes.find(d=>d.id===+id);return `<div class="cart-line">${photo(d,'cart-thumb')}<div><div class="cart-line-title">${d.name}</div><div class="cart-line-bottom"><b>${money(d.price*n)}</b>${counter(d)}</div></div></div>`}).join('');$('#order-dot').hidden=!orders.length}
function render(){renderCategories();renderMenu();renderCart()}
function openModal(content,mode='info'){modalMode=mode;$('#modal-content').innerHTML=content;if(!$('#modal').open)$('#modal').showModal()}
function setCategory(name){category=name;query='';filter='all';$('#search').value='';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));renderCategories();renderMenu()}
document.addEventListener('click',e=>{const cat=e.target.closest('[data-category]');if(cat){setCategory(cat.dataset.category);return}const step=e.target.closest('[data-change]');if(step){const id=+step.dataset.id;const next=(cart[id]||0)+Number(step.dataset.change);if(next>99){toast('每道菜最多选择 99 份');return}if(next<=0)delete cart[id];else cart[id]=next;saveLocal('shiguang-cart',cart);renderMenu();renderCart();return}const fb=e.target.closest('[data-filter]');if(fb){filter=fb.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===fb));renderMenu()}if(e.target.closest('.modal-close')||e.target.closest('[data-close]'))$('#modal').close();if(e.target.closest('#confirm-order'))submitOrder()});
$('#search').addEventListener('input',e=>{query=e.target.value.trim();if(query&&category==='人气推荐'){/* Search popular dishes within the visible category. */}renderMenu()});
$('#reset-search').onclick=()=>setCategory('人气推荐');$('#hero-btn').onclick=()=>{setCategory('招牌热菜');$('#category-title').scrollIntoView({behavior:'smooth',block:'center'})};$('#menu-nav').onclick=()=>{setCategory('人气推荐');window.scrollTo({top:0,behavior:'smooth'})};
$('#clear-cart').onclick=()=>openModal('<div class="modal-symbol">♧</div><h2>清空当前餐盘？</h2><p>已选菜品将被移除，可以重新挑选喜欢的菜。</p><button class="modal-primary" id="confirm-clear">确认清空</button><button class="modal-primary" data-close style="background:#f1f3ea;color:#777f6c">再想想</button>');
document.addEventListener('click',e=>{if(e.target.id==='confirm-clear'){cart={};saveLocal('shiguang-cart',cart);render();$('#modal').close();toast('餐盘已清空')}});
$('#mobile-cart').onclick=()=>{const open=$('#cart').classList.toggle('mobile-open');$('#mobile-cart').setAttribute('aria-expanded',open)};
$('#service-btn').onclick=()=>openModal('<div class="modal-symbol">♧</div><h2>需要一点帮助？</h2><p>可以请店内服务员协助加水、拿餐具或介绍菜品。</p><div class="modal-note">当前为点餐体验页面，暂未连接门店呼叫设备。实际用餐时，请向店内服务员示意。</div><button class="modal-primary" data-close>我知道了</button>');
$('#about-nav').onclick=()=>openModal('<div class="modal-symbol">食</div><div class="eyebrow">SHIGUANG KITCHEN · EST. 2018</div><h2>一餐一饭，都是好时光。</h2><p>食光小馆是一家示例家常菜餐厅。我们把熟悉的烟火气，装进每一道朴实的菜里。新鲜食材、现点现炒，陪你好好吃一顿饭。</p><div class="modal-note">示例营业时间 · 11:00–14:00 / 17:00–21:00<br>此页面用于点餐流程演示，菜品与价格均为示例。</div><button class="modal-primary" data-close>去看看菜单</button>');
$('#checkout').onclick=()=>{if(!totals().count)return;const {count,amount}=totals();openModal(`<div class="eyebrow">YOUR DELICIOUS MOMENT</div><h2>确认这份美味</h2><p>堂食 · 08 桌 · ${escapeHTML($('#guests').value)} · 共 ${count} 份</p>${Object.entries(cart).map(([id,n])=>{const d=dishes.find(d=>d.id===+id);return `<div class="receipt-line"><span>${d.name} × ${n}</span><b>${money(d.price*n)}</b></div>`}).join('')}<div class="receipt-line receipt-total"><span>合计</span><b>${money(amount)}</b></div>${$('#order-note').value.trim()?`<div class="modal-note">备注：${escapeHTML($('#order-note').value.trim())}</div>`:''}<p>体验订单会保存在当前浏览器，不会发送给门店，也不会产生支付。</p><button class="modal-primary" id="confirm-order">确认提交体验订单</button>`,'checkout')};
function submitOrder(){if(modalMode!=='checkout'||!totals().count)return;modalMode='submitted';const {amount,count}=totals();const o={id:'SG'+Date.now().toString().slice(-8),time:new Date().toLocaleString('zh-CN',{hour12:false}),guests:$('#guests').value,items:Object.entries(cart).map(([id,n])=>{const d=dishes.find(d=>d.id===+id);return {name:d.name,quantity:n,price:d.price}}),amount,count,note:$('#order-note').value.trim()};orders.unshift(o);orders=orders.slice(0,30);const saved=saveLocal('shiguang-orders',orders);cart={};saveLocal('shiguang-cart',cart);$('#order-note').value='';$('#cart').classList.remove('mobile-open');render();openModal(`<div class="modal-symbol">✓</div><h2>美味已记录</h2><p>体验订单 ${o.id}<br>堂食 · 08 桌 · ${escapeHTML(o.guests)} · ${money(amount)}</p><div class="modal-note">${saved?'订单已保存在本机，可在「我的订单」中查看。':'浏览器未允许本地保存，本次订单仅在当前页面保留。'}<br>这是模拟下单，尚未连接门店或支付服务。</div><button class="modal-primary" data-close>继续逛逛菜单</button>`,'success')}
$('#orders-nav').onclick=()=>openModal(`<div class="eyebrow">YOUR FOOD MEMORIES</div><h2>我的订单</h2><p>当前浏览器中的体验订单记录</p><div class="history-list">${orders.length?orders.map(o=>`<article class="history-card"><b>${escapeHTML(o.id)} <span style="float:right;color:#dc704b">${money(Number(o.amount)||0)}</span></b><small>${escapeHTML(o.time)} · 08 桌 · ${escapeHTML(o.guests)}</small><p>${o.items.map(i=>`${escapeHTML(i.name)} × ${Number(i.quantity)||0}`).join('、')}</p>${o.note?`<small>备注：${escapeHTML(o.note)}</small>`:''}<small>体验订单 · 仅保存在本机</small></article>`).join(''):'<div class="cart-empty"><div>♧</div><b>还没有订单</b><p>选几道喜欢的菜，开启第一份食光。</p></div>'}</div><button class="modal-primary" data-close>继续点餐</button>`,'history');
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open){e.preventDefault();$('#search').focus()}});render();